import Foundation

/// Itinerary identifier, generated by the app when the editor opens so that a save can be
/// replayed without creating a duplicate (ADR-008 §4, ADR-030 §6).
struct ItineraryID: Hashable, Sendable, CustomStringConvertible {
    let rawValue: UUID

    init(_ rawValue: UUID = UUID()) {
        self.rawValue = rawValue
    }

    init?(_ string: String) {
        guard let uuid = UUID(uuidString: string) else { return nil }
        rawValue = uuid
    }

    var description: String { rawValue.uuidString.lowercased() }
}
